"""Confirmed MD Parking JSON-RPC read-only client.

Secrets are supplied at runtime only and never logged.
"""
from __future__ import annotations

import json
import urllib.request
from urllib.error import HTTPError, URLError
from dataclasses import asdict, dataclass
from pathlib import Path


class ProviderError(RuntimeError):
    def __init__(self, message: str, safe_code: str = 'provider_error'):
        super().__init__(message)
        self.safe_code = safe_code

@dataclass
class Session:
    access_token: str
    refresh_token: str
    api_url: str

class Client:
    def __init__(self, auth_url: str, app: object, client_id: str, fingerprint: str):
        self.auth_url, self.app, self.client_id, self.fingerprint = auth_url, app, client_id, fingerprint
        self.session: Session | None = None
        self._request_id = 0

    def _rpc(self, url: str, method: str, params: dict, token: str | None = None) -> object:
        self._request_id += 1
        # Match the official client's compact JSON and public transport headers.
        body = json.dumps(
            {'params':params,'method':method,'jsonrpc':'2.0','id':self._request_id},
            separators=(',',':'),
        ).encode()
        headers = {
            'app-platform':'android',
            'Accept':'application/json, text/plain, */*',
            'Content-Type':'application/json',
            'User-Agent':'okhttp/4.9.2',
        }
        if token: headers['Authorization'] = f'Bearer {token}'
        request = urllib.request.Request(url, body, headers, method='POST')
        try:
            with urllib.request.urlopen(request, timeout=20) as response: payload=json.loads(response.read())
        except HTTPError as exc: raise ProviderError('provider HTTP request failed',f'http_{exc.code}') from exc
        except URLError as exc: raise ProviderError('provider connection failed',f'network_{type(exc.reason).__name__}') from exc
        except TimeoutError as exc: raise ProviderError('provider request timed out','timeout') from exc
        except (json.JSONDecodeError,UnicodeDecodeError) as exc: raise ProviderError('invalid provider JSON','invalid_json') from exc
        error=payload.get('error')
        if error:
            code=error.get('code') if isinstance(error,dict) else 'unknown'
            message=error.get('message') if isinstance(error,dict) else None
            # The first getCode call uses this error as a normal protocol branch:
            # it tells the client to request the user's object number.
            if method == 'getCode' and code == -32099 and message == 'object required':
                raise ProviderError('object number required','object_required')
            raise ProviderError('provider returned an error',f'rpc_{code}')
        return payload.get('result')

    def request_code(self, phone: str, object_id: str | None = None) -> object:
        params={'phone':phone,'clientId':self.client_id,'fingerprint':self.fingerprint}
        if object_id: params['objectId']=object_id
        try:
            return self._rpc(self.auth_url,'getCode',params)
        except ProviderError as exc:
            if not object_id and exc.safe_code == 'object_required':
                return {'objectRequired':True}
            raise

    def authorize(self, phone: str, object_id: str, code: str) -> Session:
        result=self._rpc(self.auth_url,'authorization',{'phone':phone,'objectId':object_id,'code':code,'clientId':self.client_id,'app':self.app})
        if not isinstance(result,dict) or not all(isinstance(result.get(k),str) for k in ('accessToken','refreshToken','appServer')): raise ProviderError('invalid authorization response')
        self.session=Session(result['accessToken'],result['refreshToken'],result['appServer'])
        return self.session

    def refresh_session(self) -> Session:
        if not self.session: raise ProviderError('not authorized')
        # MD Parking requires the current access token as a Bearer credential
        # even though the refresh token is also present in the RPC payload.
        result=self._rpc(
            self.auth_url,
            'updToken',
            {'refreshToken':self.session.refresh_token,'clientId':self.client_id,'app':self.app},
            self.session.access_token,
        )
        if not isinstance(result,dict) or not all(isinstance(result.get(k),str) for k in ('accessToken','refreshToken','appServer')): raise ProviderError('invalid refresh response')
        self.session=Session(result['accessToken'],result['refreshToken'],result['appServer'])
        return self.session

    def save_session(self, path: Path) -> None:
        if not self.session: raise ProviderError('not authorized')
        path.write_text(json.dumps(asdict(self.session)),encoding='utf-8')
        path.chmod(0o600)

    def load_session(self, path: Path) -> bool:
        try: value=json.loads(path.read_text(encoding='utf-8'))
        except (FileNotFoundError,json.JSONDecodeError): return False
        if not all(isinstance(value.get(k),str) for k in ('access_token','refresh_token','api_url')): return False
        self.session=Session(**value); return True

    def inventory(self) -> list[dict]:
        if not self.session: raise ProviderError('not authorized')
        objects=self._rpc(self.session.api_url,'getObjects',{'id':'all'},self.session.access_token)
        return objects.get('objects',[]) if isinstance(objects,dict) else []

    def checkpoints(self, object_id: str) -> list[dict]:
        if not self.session: raise ProviderError('not authorized')
        result=self._rpc(self.session.api_url,'getCheckpoints',{'id':object_id},self.session.access_token)
        return result.get('checkpoints',[]) if isinstance(result,dict) else []

    def access(self, acs_id: str) -> object:
        if not self.session: raise ProviderError('not authorized')
        return self._rpc(self.session.api_url,'getAccess',{'acsId':acs_id},self.session.access_token)

    def stream(self, channel: str) -> str:
        """Get a short-lived signed RTSP capability; never log or expose it."""
        if not self.session: raise ProviderError('not authorized')
        result=self._rpc(self.session.api_url,'getStream',{'channel':channel},self.session.access_token)
        if not isinstance(result,dict): raise ProviderError('invalid stream response')
        stream=result.get('stream')
        if isinstance(stream,str) and stream: return stream
        if isinstance(stream,dict):
            for quality in ('hiRes','lowRes'):
                source=stream.get(quality)
                if isinstance(source,str) and source: return source
        raise ProviderError('invalid stream response')
